def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Step 1: Find separator color from uniform rows
    sep_color = None
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            sep_color = grid[r][0]
            break

    if sep_color is None:
        return output

    # Step 2: Find separator row indices
    sep_rows = sorted(r for r in range(rows) if all(grid[r][c] == sep_color for c in range(cols)))

    # Step 3: Find separator col indices
    sep_cols = sorted(c for c in range(cols) if all(grid[r][c] == sep_color for r in range(rows)))

    # Step 4: Define row bands
    row_bands = []
    start = 0
    for r in sep_rows:
        if r > start:
            row_bands.append((start, r - 1))
        start = r + 1
    row_bands.append((start, rows - 1))

    # Step 5: Define col bands
    col_bands = []
    start = 0
    for c in sep_cols:
        if c > start:
            col_bands.append((start, c - 1))
        start = c + 1
    col_bands.append((start, cols - 1))

    # Step 6: Find background color
    counts = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != sep_color:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg_color = max(counts, key=counts.get) if counts else 0

    # Step 7: For each row band, scan left-to-right and fill blocks
    for r_bs, r_be in row_bands:
        # Collect intruders for this row band
        row_intruders = {}  # (row_rel, rel_col) -> intruder_val
        for r in range(r_bs, r_be + 1):
            for c_start, c_end in col_bands:
                for rel_c in range(c_end - c_start + 1):
                    c = c_start + rel_c
                    val = grid[r][c]
                    if val != sep_color and val != bg_color:
                        row_rel = r - r_bs
                        if (row_rel, rel_c) not in row_intruders:
                            row_intruders[(row_rel, rel_c)] = val

        # Propagate: for each row, fill from left to right
        filled_pos = {}  # track which (row_rel, rel_col) has been filled
        for r in range(r_bs, r_be + 1):
            row_rel = r - r_bs
            for c_start, c_end in col_bands:
                for rel_c in range(c_end - c_start + 1):
                    c = c_start + rel_c
                    if (row_rel, rel_c) in row_intruders and (row_rel, rel_c) not in filled_pos:
                        output[r][c] = row_intruders[(row_rel, rel_c)]
                        filled_pos[(row_rel, rel_c)] = True

    return output
